def parse_duration(s: str) -> int:
    if not s:
        raise ValueError("Empty duration string")

    total_seconds = 0
    current_num = ""

    units = {'s': 1, 'm': 60, 'h': 3600}
    last_unit_seen = None

    i = 0
    n = len(s)

    while i < n:
        char = s[i]

        if char.isdigit():
            current_num += char
            i += 1
        elif char in units:
            if not current_num:
                raise ValueError(f"Missing number before unit '{char}'")

            num = int(current_num)
            unit = char

            # Check for duplicate or out-of-order units
            if last_unit_seen == unit:
                raise ValueError(f"Duplicate unit '{unit}'")
            if last_unit_seen is not None and list(units.keys()).index(unit) < list(units.keys()).index(last_unit_seen):
                raise ValueError("Units must be in order h, m, s")

            total_seconds += num * units[unit]
            current_num = ""
            last_unit_seen = unit
            i += 1
        else:
            raise ValueError(f"Invalid character '{char}'")

    if current_num:
        raise ValueError("Trailing number without unit")

    if total_seconds == 0:
        raise ValueError("Invalid duration string")

    return total_seconds
