def compare_versions(a: str, b: str) -> int:
    def parse_version(v_str: str):
        # Split off metadata
        if '+' in v_str:
            v_base, _ = v_str.split('+', 1)
        else:
            v_base = v_str

        # Split pre-release
        if '-' in v_base:
            base, pre_rel = v_base.split('-', 1)
        else:
            base = v_base
            pre_rel = None

        # Parse core version numbers
        parts = []
        for part in base.split('.'):
            try:
                parts.append(int(part))
            except ValueError:
                # If not a pure number, keep as string (though semver core should be numeric)
                parts.append(part)

        return parts, pre_rel

    def compare_pre_release(pre_a, pre_b):
        # Pre-release without suffix is higher than with suffix (release > pre-release)
        if pre_a is None and pre_b is None:
            return 0
        if pre_a is None:
            return 1
        if pre_b is None:
            return -1

        identifiers_a = pre_a.split('.')
        identifiers_b = pre_b.split('.')

        for id_a, id_b in zip(identifiers_a, identifiers_b):
            # Check if both are numeric
            a_is_num = id_a.isdigit()
            b_is_num = id_b.isdigit()

            if a_is_num and b_is_num:
                num_a = int(id_a)
                num_b = int(id_b)
                if num_a < num_b:
                    return -1
                elif num_a > num_b:
                    return 1
            else:
                # Numeric identifiers have lower precedence than alphanumeric
                if a_is_num and not b_is_num:
                    return -1
                elif not a_is_num and b_is_num:
                    return 1
                else:
                    # Both are strings, compare lexicographically
                    if id_a < id_b:
                        return -1
                    elif id_a > id_b:
                        return 1

        # If all compared identifiers are equal, the shorter list is lower
        if len(identifiers_a) < len(identifiers_b):
            return -1
        elif len(identifiers_a) > len(identifiers_b):
            return 1

        return 0

    parts_a, pre_a = parse_version(a)
    parts_b, pre_b = parse_version(b)

    # Compare core version
    min_len = min(len(parts_a), len(parts_b))
    for i in range(min_len):
        val_a = parts_a[i]
        val_b = parts_b[i]
        if val_a < val_b:
            return -1
        elif val_a > val_b:
            return 1

    # If core versions are equal, compare pre-release
    result = compare_pre_release(pre_a, pre_b)
    if result != 0:
        return result

    # If core versions differ in length (and earlier parts were equal), shorter is lower
    if len(parts_a) < len(parts_b):
        return -1
    elif len(parts_a) > len(parts_b):
        return 1

    return 0
