def build_order(deps: dict[str, list[str]]) -> list[str]:
    # Collect all nodes: keys and all values in deps
    all_nodes = set(deps.keys())
    for dependents in deps.values():
        all_nodes.update(dependents)

    # Build adjacency list and in-degree count
    # Graph: edge from dependency to dependent
    # i.e., if A depends on B, then B must come before A
    # So edge B -> A
    adj = {node: [] for node in all_nodes}
    in_degree = {node: 0 for node in all_nodes}

    for node, dependencies in deps.items():
        for dep in dependencies:
            adj[dep].append(node)
            in_degree[node] += 1

    # Kahn's algorithm with alphabetical ordering for ties
    import heapq

    # Min-heap to process nodes with in_degree 0
    heap = []
    for node in all_nodes:
        if in_degree[node] == 0:
            heapq.heappush(heap, node)

    result = []
    while heap:
        node = heapq.heappop(heap)
        result.append(node)

        for neighbor in adj[node]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                heapq.heappush(heap, neighbor)

    # Check for cycles
    if len(result) != len(all_nodes):
        raise ValueError("Cycle detected")

    return result
