import unicodedata


def sort_names(names: list[str]) -> list[str]:
    def sort_key(name: str):
        # Remove accents and convert to lowercase for primary comparison
        normalized = ''.join(
            c for c in unicodedata.normalize('NFD', name)
            if unicodedata.category(c) != 'Mn'
        ).lower()

        # Check if original name has accents (composed characters with combining marks after normalization)
        has_accents = len(name) != len(unicodedata.normalize('NFC', unicodedata.normalize('NFD', name)))

        return (normalized, 0 if not has_accents else 1, name)

    return sorted(names, key=sort_key)
