def wrap(text: str, width: int) -> list[str]:
    if not text.strip():
        return []

    # Split by whitespace to get words
    words = text.split()

    if not words:
        return []

    lines = []
    current_line = []
    current_length = 0

    for word in words:
        # Calculate length of word as it would appear on the line (with space if not first)
        if current_line:
            needed_length = current_length + 1 + len(word)
        else:
            needed_length = len(word)

        if needed_length <= width:
            current_line.append(word)
            current_length = needed_length
        else:
            # Start a new line
            lines.append(" ".join(current_line))
            current_line = [word]
            current_length = len(word)

    # Add the last line
    if current_line:
        lines.append(" ".join(current_line))

    return lines
