def deep_merge(base: dict, override: dict) -> dict:
    result = {}

    # Add all keys from base
    for key in base:
        if key not in override or override[key] is None:
            if isinstance(base[key], dict):
                result[key] = _deep_copy_dict(base[key])
            elif isinstance(base[key], list):
                result[key] = base[key][:]  # Shallow copy of list
            else:
                result[key] = base[key]

    # Process override keys
    for key in override:
        if override[key] is None:
            # Delete key (do not include in result)
            pass
        elif isinstance(override[key], dict):
            if key in base and isinstance(base[key], dict):
                # Merge recursively
                merged = deep_merge(base[key], override[key])
                result[key] = merged
            else:
                result[key] = _deep_copy_dict(override[key])
        elif isinstance(override[key], list):
            result[key] = override[key][:]  # Shallow copy of list
        else:
            result[key] = override[key]

    return result

def _deep_copy_dict(d):
    """Recursively deep copy a dictionary."""
    result = {}
    for key, value in d.items():
        if isinstance(value, dict):
            result[key] = _deep_copy_dict(value)
        elif isinstance(value, list):
            result[key] = value[:]  # Shallow copy of lists during deep copy
        else:
            result[key] = value
    return result
