def ip_allowed(ip: str, networks: list[str]) -> bool:
    try:
        # Try to parse the IP address
        try:
            ip_addr = ipaddress.ip_address(ip)
        except ValueError:
            return False

        # Convert IPv4-mapped IPv6 addresses to IPv4
        if isinstance(ip_addr, ipaddress.IPv6Address) and ip_addr.ipv4_mapped is not None:
            ip_addr = ip_addr.ipv4_mapped

        for network_str in networks:
            try:
                network = ipaddress.ip_network(network_str, strict=False)
            except ValueError:
                raise ValueError(f"Invalid network: {network_str}")

            # Normalize the IP to match the address version of the network
            check_ip = ip_addr
            if isinstance(check_ip, ipaddress.IPv6Address):
                if check_ip.ipv4_mapped is not None and isinstance(network.ip, ipaddress.IPv4Address):
                    check_ip = check_ip.ipv4_mapped

            # Check if the IP is in the network
            try:
                if check_ip in network:
                    return True
            except TypeError:
                # Version mismatch (e.g., IPv4 in IPv6 network without mapped address)
                continue

        return False
    except ValueError as e:
        raise e
