from datetime import date, timedelta


def add_business_days(d: date, n: int, holidays: set[date]) -> date:
    """
    Moves n business days (Monday to Friday, not in holidays) from d.
    n may be negative.
    d itself never counts as one of the n days.
    With n == 0, return d if it is a business day, otherwise the next business day.
    """
    # Helper function to check if a date is a business day
    def is_business_day(dt: date) -> bool:
        # Monday=0, Sunday=6; business days are Monday-Friday (0-4)
        if dt.weekday() > 4:
            return False
        if dt in holidays:
            return False
        return True

    def next_business_day(dt: date) -> date:
        """Return the first business day strictly after dt."""
        candidate = dt + timedelta(days=1)
        while not is_business_day(candidate):
            candidate += timedelta(days=1)
        return candidate

    def prev_business_day(dt: date) -> date:
        """Return the last business day strictly before dt."""
        candidate = dt - timedelta(days=1)
        while not is_business_day(candidate):
            candidate -= timedelta(days=1)
        return candidate

    if n == 0:
        # If d itself is a business day, return it; otherwise next business day
        if is_business_day(d):
            return d
        else:
            return next_business_day(d)

    current = d

    if n > 0:
        for _ in range(n):
            current = next_business_day(current)
    else:
        # n < 0, move backwards
        for _ in range(-n):
            current = prev_business_day(current)

    return current
