def compare_versions(a: str, b: str) -> int:
    def parse_version(v):
        # Split off build metadata
        if '+' in v:
            v = v[:v.index('+')]

        # Split into main version and pre-release
        if '-' in v:
            base, pre = v.split('-', 1)
        else:
            base, pre = v, None

        # Parse numeric part
        parts = [int(p) for p in base.split('.')]

        # Parse pre-release identifiers
        pr_identifiers = []
        if pre is not None:
            pr_identifiers = pre.split('.')

        return (parts, pr_identifiers)

    def compare_identifier(a_id, b_id):
        """Compare two pre-release identifiers."""
        a_is_numeric = a_id.isdigit()
        b_is_numeric = b_id.isdigit()

        if a_is_numeric and b_is_numeric:
            # Both numeric: compare as integers
            a_num = int(a_id)
            b_num = int(b_id)
            if a_num < b_num:
                return -1
            elif a_num > b_num:
                return 1
            else:
                return 0
        elif a_is_numeric and not b_is_numeric:
            # Numeric is lower than alphanumeric
            return -1
        elif not a_is_numeric and b_is_numeric:
            # Alphanumeric is higher than numeric
            return 1
        else:
            # Both alphanumeric: compare as strings
            if a_id < b_id:
                return -1
            elif a_id > b_id:
                return 1
            else:
                return 0

    def compare_pre_release(pre_a, pre_b):
        """Compare pre-release identifier lists."""
        # If both have no pre-release, they are equal in this aspect
        if pre_a is None and pre_b is None:
            return 0
        # A version without pre-release is higher than one with pre-release
        if pre_a is None and pre_b is not None:
            return 1
        if pre_a is not None and pre_b is None:
            return -1

        # Compare identifier by identifier
        len_a = len(pre_a)
        len_b = len(pre_b)
        min_len = min(len_a, len_b)

        for i in range(min_len):
            cmp = compare_identifier(pre_a[i], pre_b[i])
            if cmp != 0:
                return cmp

        # If all compared identifiers are equal, shorter list is lower
        if len_a < len_b:
            return -1
        elif len_a > len_b:
            return 1
        else:
            return 0

    parts_a, pr_a = parse_version(a)
    parts_b, pr_b = parse_version(b)

    # Compare major.minor.patch
    for pa, pb in zip(parts_a, parts_b):
        if pa < pb:
            return -1
        elif pa > pb:
            return 1

    # If numeric parts are equal, compare pre-release
    return compare_pre_release(pr_a, pr_b)
