def wrap(text: str, width: int) -> list[str]:
    if not text.strip():
        return []

    # Split into words based on whitespace
    words = text.split()

    if not words:
        return []

    lines = []
    current_line = ""

    for word in words:
        # Check if adding this word to the current line exceeds width
        if current_line == "":
            # First word on a new line
            if len(word) > width:
                # Split the word into chunks of width
                while len(word) > width:
                    chunk = word[:width]
                    lines.append(chunk)
                    word = word[width:]
                if word:
                    current_line = word
                else:
                    current_line = ""
            else:
                current_line = word
        else:
            # Try to add a space and the new word
            if len(current_line) + 1 + len(word) <= width:
                current_line += " " + word
            else:
                # Current line is full, save it and start a new one
                lines.append(current_line)
                if len(word) > width:
                    # Split the word into chunks of width
                    while len(word) > width:
                        chunk = word[:width]
                        lines.append(chunk)
                        word = word[width:]
                    if word:
                        current_line = word
                    else:
                        current_line = ""
                else:
                    current_line = word

    # Don't forget the last line if it's not empty
    if current_line:
        lines.append(current_line)

    return lines
