def deep_merge(base: dict, override: dict) -> dict:
    def deep_copy(obj):
        if isinstance(obj, dict):
            return {k: deep_copy(v) for k, v in obj.items()}
        elif isinstance(obj, list):
            return [deep_copy(item) for item in obj]
        else:
            return obj

    result = {}

    # First, take all keys from base that are not being overridden or deleted
    for key, val in base.items():
        if key in override:
            ovr_val = override[key]
            if ovr_val is None:
                # Delete key
                continue
            elif isinstance(ovr_val, dict) and isinstance(val, dict):
                # Merge recursively
                result[key] = deep_merge(val, ovr_val)
            else:
                # Override replaces value; make a deep copy of the override value
                result[key] = deep_copy(ovr_val)
        else:
            # Key only in base; make a deep copy
            result[key] = deep_copy(val)

    # Add new keys from override that are not None and not already handled (i.e., not in base)
    for key, val in override.items():
        if key not in base:
            if val is not None:
                result[key] = deep_copy(val)

    return result
