from datetime import datetime


def latest_by_key(records: list[dict], key: str) -> list[dict]:
    # Dictionary to store the best record for each key value
    best_records = {}
    # Dictionary to track the index of first appearance of each key value
    first_appearance_index = {}

    for idx, record in enumerate(records):
        k = record.get(key)
        if k is None:
            continue

        updated_at_str = record.get('updated_at')
        if updated_at_str is None:
            continue

        # Parse the ISO 8601 datetime string
        try:
            dt = datetime.fromisoformat(updated_at_str)
        except (ValueError, TypeError):
            continue

        # If this key value hasn't been seen yet, store it
        if k not in best_records:
            best_records[k] = {
                'record': record,
                'dt': dt,
                'index': idx
            }
            first_appearance_index[k] = idx
        else:
            # Compare with the current best
            best_entry = best_records[k]
            current_best_dt = best_entry['dt']

            # Compare actual instants (datetime objects with timezone info support direct comparison)
            if dt > current_best_dt:
                best_records[k]['record'] = record
                best_records[k]['dt'] = dt
                best_records[k]['index'] = idx
            elif dt == current_best_dt:
                # On tie, keep the one that comes later in the list
                if idx > best_entry['index']:
                    best_records[k]['record'] = record
                    best_records[k]['dt'] = dt
                    best_records[k]['index'] = idx

    # Sort by first appearance order of each key value
    sorted_keys = sorted(best_records.keys(), key=lambda k: first_appearance_index[k])

    return [best_records[k]['record'] for k in sorted_keys]
