import decimal
from decimal import Decimal


def reached(value, threshold) -> bool:
    if isinstance(value, bool) or isinstance(threshold, bool):
        raise TypeError

    valid_types = (int, float, Decimal)
    if not isinstance(value, valid_types):
        raise TypeError
    if not isinstance(threshold, valid_types):
        raise TypeError

    # Convert to Decimal for comparison.
    # For floats, convert via string representation to get the shortest decimal form.
    def to_decimal(v):
        if isinstance(v, Decimal):
            return v
        elif isinstance(v, int):
            return Decimal(v)
        elif isinstance(v, float):
            # Convert float to its shortest decimal representation.
            # repr(float) gives a sufficient string representation.
            return Decimal(repr(v))

    dec_value = to_decimal(value)
    dec_threshold = to_decimal(threshold)

    return dec_value >= dec_threshold
