from collections import deque

def build_order(deps: dict[str, list[str]]) -> list[str]:
    # Build graph and in-degree map
    all_items = set(deps.keys())
    for dep_list in deps.values():
        for d in dep_list:
            all_items.add(d)

    # Initialize in-degrees to 0 for all items
    in_degree = {item: 0 for item in all_items}
    # Build adjacency list: dependency -> dependent
    # If A depends on B, then B must come before A.
    # So edge is B -> A
    adj = {item: [] for item in all_items}

    for item, dep_list in deps.items():
        for d in dep_list:
            if d not in adj:
                adj[d] = []
            adj[d].append(item)
            in_degree[item] += 1

    # Kahn's algorithm with alphabetical ordering among ready nodes
    # Use a sorted list or heap to always pick alphabetically smallest ready node
    import heapq

    # Min-heap for ready nodes (alphabetically smallest first)
    heap = []
    for item in all_items:
        if in_degree[item] == 0:
            heapq.heappush(heap, item)

    result = []
    while heap:
        current = heapq.heappop(heap)
        result.append(current)

        for neighbor in adj[current]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                heapq.heappush(heap, neighbor)

    if len(result) != len(all_items):
        raise ValueError("Cycle detected")

    return result
