def wrap(text: str, width: int) -> list[str]:
    if not text.strip():
        return []

    # Split text into words based on whitespace
    words = text.split()

    if not words:
        return []

    lines = []
    current_line = ""

    for word in words:
        # If the line is empty, start a new line
        if not current_line:
            current_line = word
        else:
            # Check if adding this word exceeds the width
            if len(current_line) + 1 + len(word) <= width:
                current_line += " " + word
            else:
                lines.append(current_line)
                current_line = word

    # Add the last line if it exists
    if current_line:
        lines.append(current_line)

    return lines
