def deep_merge(base: dict, override: dict) -> dict:
    result = {}
    keys = set(list(base.keys()) + list(override.keys()))

    for key in keys:
        if key in override:
            # If override value is None, delete the key (skip it)
            if override[key] is None:
                continue

            # If both values are dicts, merge them recursively
            if isinstance(base.get(key), dict) and isinstance(override[key], dict):
                result[key] = deep_merge(base[key], override[key])
            else:
                # Otherwise, use the override value (replace lists/other values)
                if isinstance(override[key], dict):
                    result[key] = {k: v for k, v in override[key].items()}
                elif isinstance(override[key], list):
                    result[key] = [item for item in override[key]]
                else:
                    result[key] = override[key]
        else:
            # Key only in base, copy it safely (deep copy)
            value = base[key]
            if isinstance(value, dict):
                result[key] = {k: v for k, v in value.items()}
            elif isinstance(value, list):
                result[key] = [item for item in value]
            else:
                result[key] = value

    return result
