def latest_by_key(records: list[dict], key: str) -> list[dict]:
    """
    Keeps one record per value of record[key]: the one with the latest 'updated_at'.
    updated_at is an ISO 8601 string that may use different UTC offsets.
    On a tie, keep the record that comes later in the list.
    Return the records in the order in which each key first appeared.
    """
    from datetime import datetime, timezone

    def parse_iso_datetime(dt_str: str) -> datetime:
        """Parse an ISO 8601 datetime string into a timezone-aware datetime object."""
        # Replace 'Z' with '+00:00' for standard parsing
        if dt_str.endswith('Z'):
            dt_str = dt_str[:-1] + '+00:00'
        return datetime.fromisoformat(dt_str)

    # Dictionary to store the best record for each key value
    # Key: value of record[key], Value: (datetime, index, record)
    best_records = {}

    # Track the order in which each key first appeared
    key_order = []
    key_set = set()

    for idx, record in enumerate(records):
        if key not in record or 'updated_at' not in record:
            continue

        key_value = record[key]
        updated_at_str = record['updated_at']

        try:
            updated_at_dt = parse_iso_datetime(updated_at_str)
        except (ValueError, TypeError):
            continue

        if key_value not in key_set:
            key_set.add(key_value)
            key_order.append(key_value)
            best_records[key_value] = (updated_at_dt, idx, record)
        else:
            current_best_dt, current_best_idx, current_best_record = best_records[key_value]
            # Compare the actual instants; on tie, keep the one that comes later in the list
            if updated_at_dt > current_best_dt or (updated_at_dt == current_best_dt and idx > current_best_idx):
                best_records[key_value] = (updated_at_dt, idx, record)

    # Return records in the order each key first appeared
    result = []
    for k in key_order:
        if k in best_records:
            result.append(best_records[k][2])

    return result
